/// @brief Enumeration for error codes of URL download.
/// @since_tizen 2.3
abstract class download_error_e {
  /// < Successful
  static const int DOWNLOAD_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int DOWNLOAD_ERROR_INVALID_PARAMETER = -22;

  /// < Out of memory
  static const int DOWNLOAD_ERROR_OUT_OF_MEMORY = -12;

  /// < Network is unreachable
  static const int DOWNLOAD_ERROR_NETWORK_UNREACHABLE = -101;

  /// < HTTP session time-out
  static const int DOWNLOAD_ERROR_CONNECTION_TIMED_OUT = -110;

  /// < No space left on device
  static const int DOWNLOAD_ERROR_NO_SPACE = -28;

  /// < Permission denied
  static const int DOWNLOAD_ERROR_PERMISSION_DENIED = -13;

  /// < Not supported
  static const int DOWNLOAD_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Invalid state
  static const int DOWNLOAD_ERROR_INVALID_STATE = -44040159;

  /// < Connection failed
  static const int DOWNLOAD_ERROR_CONNECTION_FAILED = -44040158;

  /// < Invalid URL
  static const int DOWNLOAD_ERROR_INVALID_URL = -44040156;

  /// < Invalid destination
  static const int DOWNLOAD_ERROR_INVALID_DESTINATION = -44040155;

  /// < Too many simultaneous downloads
  static const int DOWNLOAD_ERROR_TOO_MANY_DOWNLOADS = -44040154;

  /// < Download server queue is full
  static const int DOWNLOAD_ERROR_QUEUE_FULL = -44040153;

  /// < The download is already completed
  static const int DOWNLOAD_ERROR_ALREADY_COMPLETED = -44040152;

  /// < Failed to rename the downloaded file
  static const int DOWNLOAD_ERROR_FILE_ALREADY_EXISTS = -44040151;

  /// < Cannot resume
  static const int DOWNLOAD_ERROR_CANNOT_RESUME = -44040150;

  /// < Specified field not found
  static const int DOWNLOAD_ERROR_FIELD_NOT_FOUND = -44040149;

  /// < Too many redirects from HTTP response header
  static const int DOWNLOAD_ERROR_TOO_MANY_REDIRECTS = -44040144;

  /// < The download cannot handle the HTTP status value
  static const int DOWNLOAD_ERROR_UNHANDLED_HTTP_CODE = -44040143;

  /// < No action after client creates a download ID
  static const int DOWNLOAD_ERROR_REQUEST_TIMEOUT = -44040142;

  /// < No call to start API for some time although the download is created
  static const int DOWNLOAD_ERROR_RESPONSE_TIMEOUT = -44040141;

  /// < No response from client after rebooting download daemon
  static const int DOWNLOAD_ERROR_SYSTEM_DOWN = -44040140;

  /// < Download ID does not exist in download service module
  static const int DOWNLOAD_ERROR_ID_NOT_FOUND = -44040139;

  /// < Network bonding is set but network type is not set as #DOWNLOAD_NETWORK_ALL
  static const int DOWNLOAD_ERROR_INVALID_NETWORK_TYPE = -44040138;

  /// < No data because the set API is not called
  static const int DOWNLOAD_ERROR_NO_DATA = -61;

  /// < Internal I/O error
  static const int DOWNLOAD_ERROR_IO_ERROR = -5;
}

/// @brief Enumeration for download states.
/// @since_tizen 2.3
abstract class download_state_e {
  /// < Unhandled exception
  static const int DOWNLOAD_STATE_NONE = 0;

  /// < Ready to download
  static const int DOWNLOAD_STATE_READY = 1;

  /// < Queued to start downloading
  static const int DOWNLOAD_STATE_QUEUED = 2;

  /// < Currently downloading
  static const int DOWNLOAD_STATE_DOWNLOADING = 3;

  /// < The download is waiting to resume
  static const int DOWNLOAD_STATE_PAUSED = 4;

  /// < The download is completed
  static const int DOWNLOAD_STATE_COMPLETED = 5;

  /// < The download failed
  static const int DOWNLOAD_STATE_FAILED = 6;

  /// < User canceled the download item
  static const int DOWNLOAD_STATE_CANCELED = 7;
}

/// @brief Enumeration for network type for downloading.
/// @since_tizen 2.3
abstract class download_network_type_e {
  /// < Download is available through data network
  static const int DOWNLOAD_NETWORK_DATA_NETWORK = 0;

  /// < Download is available through WiFi
  static const int DOWNLOAD_NETWORK_WIFI = 1;

  /// < Download is available through WiFi-Direct
  static const int DOWNLOAD_NETWORK_WIFI_DIRECT = 2;

  /// < Download is available through either data network or WiFi
  static const int DOWNLOAD_NETWORK_ALL = 3;
}

/// @brief Enumeration for notification types when a client wants to register.
/// @since_tizen 2.3
///
/// @see download_set_notification_type()
/// @see download_get_notification_type()
abstract class download_notification_type_e {
  /// < Do not register notification
  static const int DOWNLOAD_NOTIFICATION_TYPE_NONE = 0;

  /// < Completion notification for success state and failed state
  static const int DOWNLOAD_NOTIFICATION_TYPE_COMPLETE_ONLY = 1;

  /// < All download notifications for ongoing state, success state and failed state
  static const int DOWNLOAD_NOTIFICATION_TYPE_ALL = 2;
}

/// @brief Enumeration for the type of notification app control action which the client wants to set when registering notification.
/// @since_tizen 2.3
///
/// @see download_set_notification_app_control()
/// @see download_get_notification_app_control()
abstract class download_notification_app_control_type_e {
  /// < App control action for failed and ongoing notification
  static const int DOWNLOAD_NOTIFICATION_APP_CONTROL_TYPE_ONGOING = 0;

  /// < App control action for completed notification
  static const int DOWNLOAD_NOTIFICATION_APP_CONTROL_TYPE_COMPLETE = 1;

  /// < App control action for failed notification
  static const int DOWNLOAD_NOTIFICATION_APP_CONTROL_TYPE_FAILED = 2;
}

/// @brief Called when a download state is changed.
///
/// @since_tizen 2.3
///
/// @param[in] download_id  The download ID
/// @param[in] state        The state of download
/// @param[in] user_data    The user data passed from download_set_state_changed_cb()
///
/// @pre download_start() will invoke this callback if you register this callback using download_set_state_changed_cb().
///
/// @see download_set_state_changed_cb()
/// @see download_unset_state_changed_cb()
typedef download_state_changed_cb
    = ffi.Pointer<ffi.NativeFunction<download_state_changed_cbFunction>>;
typedef download_state_changed_cbFunction = ffi.Void Function(
    ffi.Int download_id, ffi.Int32 state, ffi.Pointer<ffi.Void> user_data);
typedef Dartdownload_state_changed_cbFunction = void Function(
    int download_id, int state, ffi.Pointer<ffi.Void> user_data);

/// @brief Called when the progress of download changes.
///
/// @since_tizen 2.3
///
/// @remarks This callback function is only invoked in the downloading state.
///
/// @param[in] download_id  The download ID
/// @param[in] received     The size of the data received in bytes
/// @param[in] user_data    The user data passed from download_set_progress_cb()
///
/// @pre This callback function is invoked if you register this callback using download_set_progress_cb().
///
/// @see download_cancel()
/// @see download_set_progress_cb()
/// @see download_unset_progress_cb()
typedef download_progress_cb
    = ffi.Pointer<ffi.NativeFunction<download_progress_cbFunction>>;
typedef download_progress_cbFunction = ffi.Void Function(ffi.Int download_id,
    ffi.UnsignedLongLong received, ffi.Pointer<ffi.Void> user_data);
typedef Dartdownload_progress_cbFunction = void Function(
    int download_id, int received, ffi.Pointer<ffi.Void> user_data);
